/* Cosmetic-only fighter styling and an opt-in, north-up tactical radar. */
(function(root){
'use strict';
const SKIN={deep:[.34,.20,.14],warm:[.61,.39,.25],tan:[.76,.55,.37],light:[.89,.71,.55]},DEFAULT={skin:'warm',hair:'coils',shirt:'#c9d4b5',pants:'#293b36',accent:'#dae77d',outfit:'classic',accessory:'none',beard:'none',hairColor:'#0e0b0a',shoes:'#131a18',name:'YOU'},PRESETS={original:DEFAULT,ember:{skin:'deep',hair:'swept',shirt:'#aa452f',pants:'#25272f',accent:'#ffbc59'},tide:{skin:'tan',hair:'braid',shirt:'#326d85',pants:'#1c353f',accent:'#9ce8e4'},jade:{skin:'warm',hair:'crop',shirt:'#497153',pants:'#27382f',accent:'#dbce84'}};
PRESETS.storm={...DEFAULT,shirt:'#426181',pants:'#232b38',accent:'#bbdbf1',outfit:'sport',accessory:'visor',hair:'swept'};PRESETS.copper={...DEFAULT,skin:'deep',shirt:'#a87246',pants:'#35483a',accent:'#f1dc9a',outfit:'guard',accessory:'headband',beard:'trim'};
const color=v=>[1,3,5].map(i=>parseInt(v.slice(i,i+2),16)/255);
function sanitize(v){const out={...DEFAULT};if(typeof v?.name==='string'&&v.name.trim())out.name=v.name.trim().replace(/[<>]/g,'').slice(0,20)||'YOU';if(v&&SKIN[v.skin])out.skin=v.skin;if(v&&['coils','crop','swept','braid'].includes(v.hair))out.hair=v.hair;for(const k of ['outfit','accessory','beard'])if(({outfit:['classic','sport','guard'],accessory:['none','headband','visor'],beard:['none','trim']})[k].includes(v?.[k]))out[k]=v[k];for(const k of ['shirt','pants','accent','hairColor','shoes'])if(/^#[0-9a-f]{6}$/i.test(v?.[k]))out[k]=v[k];return out;}
let look={...DEFAULT},radar=false;
function apply(v){look=sanitize(v);root.CombatCharacter.look={skin:SKIN[look.skin],style:look.hair,hair:color(look.hairColor),outfit:look.outfit,accessory:look.accessory,beard:look.beard,shoes:color(look.shoes),shirt:color(look.shirt),pants:color(look.pants),accent:color(look.accent)};return look;}
function init({renderer}={}){try{apply(JSON.parse(localStorage.getItem('kinetic-fighter-v1')));}catch{apply(DEFAULT);}const d=document,menu=d.getElementById('field-menu-panel'),toggle=d.getElementById('field-menu-toggle'),focus=()=>d.getElementById('arena').focus({preventScroll:true});
const setMenu=open=>{menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));if(!open)focus();};toggle.addEventListener('click',()=>setMenu(menu.hidden));d.getElementById('field-menu-close').addEventListener('click',()=>setMenu(false));
const library=d.getElementById('combo-library-panel'),libraryToggle=d.getElementById('library-toggle');libraryToggle.addEventListener('click',()=>{library.hidden=!library.hidden;d.querySelector('.main-layout').classList.toggle('library-closed',library.hidden);libraryToggle.setAttribute('aria-expanded',String(!library.hidden));libraryToggle.textContent=library.hidden?'☰ Open practice panel':'× Hide practice panel';renderer?.resize();});
const sync=()=>{document.getElementById('fighter-display-name').textContent=look.name;for(const k of Object.keys(DEFAULT))d.getElementById('look-'+k).value=look[k];};
const save=v=>{apply(v);sync();try{localStorage.setItem('kinetic-fighter-v1',JSON.stringify(look));d.getElementById('look-status').textContent='Style applied · saved on this browser.';}catch{d.getElementById('look-status').textContent='Style applied for this session.';}};
for(const k of Object.keys(DEFAULT))d.getElementById('look-'+k).addEventListener('input',e=>save({...look,[k]:e.target.value}));d.querySelectorAll('[data-look]').forEach(b=>b.addEventListener('click',()=>save(PRESETS[b.dataset.look])));d.querySelectorAll('[data-look-save]').forEach(b=>b.addEventListener('click',()=>{try{localStorage.setItem('kinetic-look-slot-'+b.dataset.lookSave,JSON.stringify(look));d.getElementById('look-status').textContent='Saved slot '+b.dataset.lookSave+'.';}catch{d.getElementById('look-status').textContent='Browser storage unavailable.';}}));d.querySelectorAll('[data-look-load]').forEach(b=>b.addEventListener('click',()=>{try{const v=JSON.parse(localStorage.getItem('kinetic-look-slot-'+b.dataset.lookLoad));if(v)save(v);else d.getElementById('look-status').textContent='Save a style to this slot first.';}catch{d.getElementById('look-status').textContent='Could not load this slot.';}}));d.getElementById('look-random').addEventListener('click',()=>{const pick=a=>a[Math.floor(Math.random()*a.length)],v=pick(Object.values(PRESETS));save({...v,name:look.name,hair:pick(['coils','crop','swept','braid']),outfit:pick(['classic','sport','guard']),accessory:pick(['none','headband','visor'])});});d.getElementById('look-reset').addEventListener('click',()=>save(DEFAULT));
d.getElementById('field-radar-toggle').addEventListener('click',e=>{radar=!radar;e.currentTarget.setAttribute('aria-pressed',String(radar));setMenu(false);});sync();
}
function drawRadar(r){if(!radar)return;const c=r.ctx,w=r.world,size=r.width<500?88:112,x=r.width-size-12,y=r.height-size-28,scale=size/13;c.save();c.fillStyle='#102922dc';c.fillRect(x,y,size,size);c.strokeStyle='#8da57888';c.strokeRect(x,y,size,size);const point=(a,b)=>[x+size/2+a*scale,y+size/2+b*scale];c.fillStyle='#8ca48b';for(const p of w.yard.props){if(p.broken||p.heldBy)continue;const q=point(p.x,p.z);c.fillRect(q[0]-2,q[1]-2,4,4);}for(const f of w.fighters()){if(f.ko)continue;const q=point(f.x,f.z);c.fillStyle=f.id==='player'?'#e8f4a6':'#ff987d';c.beginPath();c.arc(q[0],q[1],f.id==='player'?4:3,0,Math.PI*2);c.fill();if(f.id==='player'){c.strokeStyle='#e8f4a6';c.beginPath();c.moveTo(...q);c.lineTo(q[0]+Math.sin(f.angle)*9,q[1]+Math.cos(f.angle)*9);c.stroke();}}c.font='8px Arial';c.fillStyle='#cfdfb6';c.textAlign='left';c.fillText('N ↑ · ARENA',x+5,y+10);c.restore();}
root.CombatStudio={init,drawRadar,sanitize,apply,PRESETS};if(typeof module!=='undefined')module.exports=root.CombatStudio;
})(typeof window!=='undefined'?window:globalThis);
